-- Bloco 1/10: 10 perguntas de O Que é o Espiritismo.
-- Seguro para executar individualmente; não altera perguntas existentes.
INSERT INTO public.questions
  (book, statement, option_a, option_b, option_c, option_d, option_e,
   correct_option, explanation, reference, difficulty, active)
VALUES
  ('''o_que_e_espiritismo''', 'Segundo a biografia escrita por Henri Sausse em ''O Que é o Espiritismo'', em que cidade e data nasceu Allan Kardec?', 'Em Lyon, a 3 de outubro de 1804.', 'Em Paris, a 18 de abril de 1804.', 'Em Bordeaux, a 31 de março de 1805.', 'Em Tours, a 3 de novembro de 1803.', 'Em Genebra, a 15 de agosto de 1804.', 'A', 'Henri Sausse registra que Allan Kardec nasceu em Lyon a 3 de outubro de 1804, recebendo o nome civil de Hippolyte Léon Denizard Rivail.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'facil', true),
  ('''o_que_e_espiritismo''', 'Qual era o nome civil completo do Codificador do Espiritismo antes de adotar o pseudônimo Allan Kardec?', 'Jean-Baptiste Léon Fortier Rivail.', 'Hippolyte Léon Denizard Rivail.', 'Pierre-Paul Didier Baudin.', 'Camille Nicolas Denizard Flammarion.', 'Henri Léon Sausse Rivail.', 'B', 'Filho do magistrado Jean-Baptiste Antoine Rivail, o Codificador chamava-se no registro civil Hippolyte Léon Denizard Rivail.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'facil', true),
  ('''o_que_e_espiritismo''', 'Em qual instituição suíça o jovem Denizard Rivail realizou seus estudos pedagógicos sob a direção de um célebre educador?', 'Na Academia de Genebra, sob a direção de Jean-Jacques Rousseau.', 'No Colégio de Lausanne, dirigido pelo pastor Charles Wagner.', 'No Instituto de Yverdon, dirigido pelo célebre professor Pestalozzi.', 'No Liceu de Zurique, dirigido por Heinrich Lavater.', 'Na Escola Politécnica de Berna, sob orientação de Girard.', 'C', 'Seus pais enviaram-no para o famoso Instituto de Yverdon, na Suíça, dirigido por Johann Heinrich Pestalozzi, de quem se tornou discípulo e colaborador.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'facil', true),
  ('''o_que_e_espiritismo''', 'Com quem o professor Hippolyte Léon Denizard Rivail se casou em 6 de fevereiro de 1832?', 'Com Ermance Dufaux.', 'Com Caroline e Julie Baudin.', 'Com Ruth Japhet.', 'Com Amélie Gabrielle Boudet.', 'Com Madame Plainemaison.', 'D', 'Em 1832, o professor Rivail desposou Amélie Gabrielle Boudet, culta professora que foi sua dedicada companheira e colaboradora durante toda a vida.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
  ('''o_que_e_espiritismo''', 'Em que ano, segundo Henri Sausse, o professor Rivail ouviu falar pela primeira vez das mesas girantes por meio do magnetizador Sr. Fortier?', 'Em 1848, logo após os fenômenos de Hydesville.', 'Em 1850, durante um congresso de magnetismo em Lyon.', 'Em 1852, na Academia Real de Ciências de Arras.', 'Em 1857, pouco antes de publicar O Livro dos Espíritos.', 'Em 1854, quando o Sr. Fortier lhe relatou que as mesas não apenas giravam, mas também falavam.', 'E', 'Foi em 1854 que o Sr. Fortier, magnetizador de suas relações, falou-lhe pela primeira vez das mesas girantes e das comunicações obtidas por batidas.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
  ('''o_que_e_espiritismo''', 'Na casa de quem, em maio de 1855, o professor Rivail presenciou pela primeira vez o fenômeno das mesas que giravam, saltavam e corriam?', 'Na casa da Sra. Plainemaison, na rua Grange-Batelière.', 'Na residência de Camille Flammarion, no Observatório de Paris.', 'No salão literário do livreiro Didier, no Palais-Royal.', 'No gabinete médico do Dr. Paul Bert.', 'No Instituto Técnico da rua de Sèvres.', 'A', 'Em maio de 1855, acompanhado do Sr. Pottié, Rivail assistiu pela primeira vez às experiências de mesas girantes e escrita em ardósia na casa da Sra. Plainemaison.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
  ('''o_que_e_espiritismo''', 'Na casa de qual família o professor Rivail iniciou seus estudos regulares e metódicos das comunicações psicográficas por meio de duas jovens médiuns?', 'Na casa da família Fortier.', 'Na casa da família Baudin, com as jovens Caroline e Julie.', 'Na casa da família Sausse, em Lyon.', 'Na casa da família Delanne, em Paris.', 'Na casa da família Lachâtre, em Toulon.', 'B', 'Foi nas reuniões semanais na casa da família Baudin, onde escreviam na cesta-pião as jovens médiuns Srta. Julie e Srta. Caroline Baudin, que Rivail iniciou seus estudos sérios.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
  ('''o_que_e_espiritismo''', 'Por meio de qual médium sonâmbula o professor Rivail fez a verificação e revisão completa dos cinquenta cadernos que deram origem a ''O Livro dos Espíritos''?', 'Sra. Plainemaison.', 'Sra. Amélie Boudet.', 'Srta. Ruth Japhet.', 'Srta. Aline Carlotti.', 'Sra. d''Espérance.', 'C', 'Cerca de cinquenta cadernos confiados pelos Srs. Carlotti, René Taillandier, Tiedeman-Manthese e Sardou foram coordenados e revistos com o concurso da médium Srta. Japhet.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'dificil', true),
  ('''o_que_e_espiritismo''', 'Em que data veio a lume a primeira edição de ''O Livro dos Espíritos'', marco inaugural da Codificação Espírita?', '1 de janeiro de 1858.', '3 de outubro de 1856.', '31 de março de 1857.', '18 de abril de 1857.', '15 de agosto de 1859.', 'D', 'A primeira edição de O Livro dos Espíritos foi publicada em Paris, pela livraria Dentu, no Palais-Royal, em 18 de abril de 1857.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'facil', true),
  ('''o_que_e_espiritismo''', 'Por que o professor Rivail decidiu assinar as obras espíritas com o pseudônimo Allan Kardec?', 'Para ocultar sua nacionalidade francesa diante das autoridades eclesiásticas.', 'Porque seu editor exigiu um nome de sonoridade inglesa para ampliar as vendas.', 'Por imposição da Academia Real de Ciências de Arras.', 'Para homenagear seu antigo mestre suíço Pestalozzi.', 'Para não confundir sua obra espírita, fruto do ensino dos Espíritos, com seus conhecidos livros pedagógicos assinados com o nome civil.', 'E', 'Sendo seu nome civil muito conhecido pelas obras didáticas e gramaticais, adotou o nome Allan Kardec — que seu Espírito protetor revelou ter sido seu em existência anterior entre os druidas — para distinguir a obra espírita.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'dificil', true);

SELECT COUNT(*) AS perguntas_do_livro
FROM public.questions
WHERE book = 'o_que_e_espiritismo';